import sys
MOD = 10**9 + 7

def main():
    input = sys.stdin.read().split()
    ptr = 0
    n, m, k = map(int, input[ptr:ptr+3])
    ptr += 3
    c = list(map(int, input[ptr:ptr+n]))
    ptr += n
    adj = [[] for _ in range(n+1)]
    for _ in range(m):
        u, v = map(int, input[ptr:ptr+2])
        ptr += 2
        adj[u].append(v)
        adj[v].append(u)

    max_x = 1 << k
    res = 0

    for x in range(max_x):
        cnt = 0
        for i in range(n):
            if (c[i] ^ x) == c[i]:
                cnt += 1
        if cnt == n:
            res = (res + pow(2, n, MOD)) % MOD
            continue

        dp = [0] * (n + 1)
        dp[0] = 1
        for i in range(n):
            new_dp = dp.copy()
            for j in range(n + 1):
                if dp[j] == 0:
                    continue
                new_j = j
                if (c[i] ^ x) == c[i]:
                    new_j += 1
                new_dp[new_j] = (new_dp[new_j] + dp[j]) % MOD
            dp = new_dp

        for mask in range(n + 1):
            valid = True
            for u in range(1, n+1):
                for v in adj[u]:
                    if v > u:
                        continue
                    u_idx = u - 1
                    v_idx = v - 1
                    u_key = c[u_idx] ^ x if (mask & (1 << u_idx)) else c[u_idx]
                    v_key = c[v_idx] ^ x if (mask & (1 << v_idx)) else c[v_idx]
                    if u_key == v_key:
                        valid = False
                        break
                if not valid:
                    break
            if valid:
                res = (res + dp[mask]) % MOD

    print(res)

main()
